export declare const codeGithubTheme = "/*\ngithub.com style (c) Vasily Polovnyov <vast@whiteants.net>\n*/\n\n/* \u4EE3\u7801\u5757\u6837\u5F0F - \u9700\u8981\u6DFB\u52A0 #wemd \u524D\u7F00\u4EE5\u5339\u914D\u5305\u88C5\u540E\u7684 HTML */\n#wemd .hljs {\n  display: block;\n  overflow-x: auto;\n  padding: 16px;\n  color: #333;\n  background: #f8f8f8;\n}\n\n#wemd .hljs-comment,\n#wemd .hljs-quote {\n  color: #998;\n  font-style: italic;\n}\n\n#wemd .hljs-keyword,\n#wemd .hljs-selector-tag,\n#wemd .hljs-subst {\n  color: #333;\n  font-weight: bold;\n}\n\n#wemd .hljs-number,\n#wemd .hljs-literal,\n#wemd .hljs-variable,\n#wemd .hljs-template-variable,\n#wemd .hljs-tag .hljs-attr {\n  color: #008080;\n}\n\n#wemd .hljs-string,\n#wemd .hljs-doctag {\n  color: #d14;\n}\n\n#wemd .hljs-title,\n#wemd .hljs-section,\n#wemd .hljs-selector-id {\n  color: #900;\n  font-weight: bold;\n}\n\n#wemd .hljs-subst {\n  font-weight: normal;\n}\n\n#wemd .hljs-type,\n#wemd .hljs-class .hljs-title {\n  color: #458;\n  font-weight: bold;\n}\n\n#wemd .hljs-tag,\n#wemd .hljs-name,\n#wemd .hljs-attribute {\n  color: #000080;\n  font-weight: normal;\n}\n\n#wemd .hljs-regexp,\n#wemd .hljs-link {\n  color: #009926;\n}\n\n#wemd .hljs-symbol,\n#wemd .hljs-bullet {\n  color: #990073;\n}\n\n#wemd .hljs-built_in,\n#wemd .hljs-builtin-name {\n  color: #0086b3;\n}\n\n#wemd .hljs-meta {\n  color: #999;\n  font-weight: bold;\n}\n\n#wemd .hljs-deletion {\n  background: #fdd;\n}\n\n#wemd .hljs-addition {\n  background: #dfd;\n}\n\n#wemd .hljs-emphasis {\n  font-style: italic;\n}\n\n#wemd .hljs-strong {\n  font-weight: bold;\n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
